//! A-06 Fluent Architecture Capture — outcome contract tests.

use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin()).args(args).current_dir(dir.path()).output().expect("run residual")
}

fn init(dir: &TempDir) {
    assert!(run(dir, &["init"]).status.success());
}

#[test]
fn skill_data_stressor_walk_succeeds_without_personas() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    assert!(run(&dir, &["skill-data", "stressor-walk"]).status.success());
}

#[test]
fn skill_list_marks_skills_as_selectable_steps() {
    let stdout = String::from_utf8_lossy(&run(&TempDir::new().unwrap(), &["skill-list"]).stdout).to_lowercase();
    assert!(stdout.contains("selectable") || stdout.contains("a-la-carte") || stdout.contains("lens"));
}

#[test]
fn skill_show_purpose_walk_describes_analytical_lens_not_mandatory_gate() {
    let stdout = String::from_utf8_lossy(&run(&TempDir::new().unwrap(), &["skill-show", "purpose-walk"]).stdout).to_lowercase();
    assert!(stdout.contains("a-la-carte") || stdout.contains("analytical lens") || stdout.contains("optional"));
}

#[test]
fn verify_all_passes_without_running_any_skill() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(&dir, &["add", "attractor", "--name", "X", "--description", "d", "--positive-state", "ok", "--negative-state", "bad"]);
    run(&dir, &["add", "term", "--term", "operator", "--definition", "human using the tool"]);
    run(&dir, &["add", "stressor", "--description", "partial", "--attractor-id", "A-01", "--naive-change", "none", "--outcomes", "operator records a stressor mid-session"]);
    assert!(run(&dir, &["verify", "all"]).status.success());
}

#[test]
fn skill_data_includes_fluent_capture_preamble() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    let stdout = String::from_utf8_lossy(&run(&dir, &["skill-data", "integrate"]).stdout).to_lowercase();
    assert!(stdout.contains("fluent") || stdout.contains("any phase") || stdout.contains("mid-session"));
}

#[test]
fn operator_adds_stressor_without_skill_invocation() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(&dir, &["add", "attractor", "--name", "Flow", "--description", "d", "--positive-state", "ok", "--negative-state", "bad"]);
    assert!(run(&dir, &["add", "stressor", "--description", "narrative lands mid-session", "--attractor-id", "A-01", "--naive-change", "capture first"]).status.success());
}

#[test]
fn add_purpose_accepts_traits_alias_for_outcomes() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(&dir, &["add", "attractor", "--name", "X", "--description", "d", "--positive-state", "ok", "--negative-state", "bad"]);
    run(&dir, &["add", "term", "--term", "operator", "--definition", "human using the tool"]);
    assert!(run(&dir, &["add", "purpose", "--description", "capture", "--attractor-id", "A-01", "--feature", "cli", "--traits", "operator records outcomes mid-session"]).status.success());
}

#[test]
fn add_purpose_accepts_naive_change_alias_for_feature() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(&dir, &["add", "attractor", "--name", "X", "--description", "d", "--positive-state", "ok", "--negative-state", "bad"]);
    assert!(run(&dir, &["add", "purpose", "--description", "outcome semantics", "--attractor-id", "A-01", "--naive-change", "rename feature toward force naive_change"]).status.success());
}

#[test]
fn purpose_walk_skill_uses_outcome_not_trait_terminology() {
    let stdout = String::from_utf8_lossy(&run(&TempDir::new().unwrap(), &["skill-show", "purpose-walk"]).stdout).to_lowercase();
    assert!(stdout.contains("outcome"));
    assert!(!stdout.contains(" trait") && !stdout.contains("traits"));
}

#[test]
fn generate_man_leads_with_fluent_entry_model() {
    let stdout = String::from_utf8_lossy(&run(&TempDir::new().unwrap(), &["generate", "man"]).stdout).to_lowercase();
    let desc_pos = stdout.find(".sh description").unwrap_or(0);
    assert!(stdout.find("fluent").or_else(|| stdout.find("a-la-carte")).is_some_and(|p| p <= desc_pos + 800));
}

